function spiralOrder(matrix: number[][]): number[] {
  const result: number[] = [];
  // Четыре границы ещё не обойдённой части матрицы (включительно)
  let top = 0;
  let bottom = matrix.length - 1;
  let left = 0;
  let right = matrix[0].length - 1;

  while (top <= bottom && left <= right) {
    // 1. Верхняя строка слева направо
    for (let c = left; c <= right; c++) result.push(matrix[top][c]);
    top++;

    // 2. Правый столбец сверху вниз
    for (let r = top; r <= bottom; r++) result.push(matrix[r][right]);
    right--;

    // 3. Нижняя строка справа налево — только если строка ещё осталась
    if (top <= bottom) {
      for (let c = right; c >= left; c--) result.push(matrix[bottom][c]);
      bottom--;
    }

    // 4. Левый столбец снизу вверх — только если столбец ещё остался
    if (left <= right) {
      for (let r = bottom; r >= top; r--) result.push(matrix[r][left]);
      left++;
    }
  }

  return result;
}

// Время: O(m · n) — каждый элемент добавляется ровно один раз
// Память: O(1) дополнительно (не считая ответа)
